15	type Finding struct {
16		Path    string
17		Line    int
18		Column  int
19		Surface string
20		Match   string
21	}
22	
23	type Options struct {
24		Root string
25		Out  io.Writer
26	}
27	
28	type rule struct {
29		surface string
30		re      *regexp.Regexp
31		rootGo  bool
32	}
33	
34	var rules = []rule{
35		{surface: "github.com/DocumentDrivenDX/agent", re: regexp.MustCompile(regexp.QuoteMeta("github.com/DocumentDrivenDX/agent"))},
36		{surface: "root package agent", re: regexp.MustCompile(`^\s*package\s+agent\s*$`), rootGo: true},
37		{surface: "ddx-agent", re: regexp.MustCompile(regexp.QuoteMeta("ddx-agent"))},
38		{surface: "DDX Agent/DDx Agent", re: regexp.MustCompile(`DD[Xx] Agent`)},
39		{surface: ".agent", re: regexp.MustCompile(`(^|[^A-Za-z0-9_])\.agent([^A-Za-z0-9_]|$)`)},
40		{surface: "~/.config/agent", re: regexp.MustCompile(regexp.QuoteMeta("~/.config/agent"))},
41		{surface: "AGENT_*/DDX_AGENT_*", re: regexp.MustCompile(`\b(?:DDX_AGENT|AGENT)_[A-Z0-9_]+\b`)},
42	}
43	
44	var skippedDirs = map[string]bool{
45		".git":                 true,
46		".ddx":                 true,
47		".agents":              true,
48		".claude":              true,
49		".helix-ratchets":      true,
50		"docs/helix":           true,
51		"docs/research":        true,
52		"internal/renamecheck": true,
53		// DDX_AGENT_* harness env vars are not yet renamed; allowlisted until a
