78	func Scan(opts Options) ([]Finding, error) {
79		root := opts.Root
80		if root == "" {
81			root = "."
82		}
83	
84		var findings []Finding
85		err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
86			if err != nil {
87				return err
88			}
89			rel, err := filepath.Rel(root, path)
90			if err != nil {
91				return err
92			}
93			rel = filepath.ToSlash(rel)
94			if rel == "." {
95				return nil
96			}
97			if d.IsDir() {
98				if shouldSkipDir(rel) {
99					return filepath.SkipDir
100				}
101				return nil
102			}
103			if skippedFiles[rel] {
104				return nil
105			}
106			if !isTextCandidate(rel) {
107				return nil
108			}
109			fileFindings, err := scanFile(root, rel)
110			if err != nil {
111				return err
112			}
113			findings = append(findings, fileFindings...)
114			return nil
115		})
116		if err != nil {
117			return nil, err
118		}
119		sort.Slice(findings, func(i, j int) bool {
120			if findings[i].Path != findings[j].Path {
121				return findings[i].Path < findings[j].Path
122			}
123			if findings[i].Line != findings[j].Line {
124				return findings[i].Line < findings[j].Line
125			}
126			return findings[i].Column < findings[j].Column
127		})
128		return findings, nil
129	}
130	
131	func Report(w io.Writer, findings []Finding) error {
132		if w == nil {
133			return nil
134		}
135		if len(findings) == 0 {
136			_, err := fmt.Fprintln(w, "rename-noise: no unallowlisted old-name hits found")
137			return err
138		}
139		if _, err := fmt.Fprintf(w, "rename-noise: %d unallowlisted old-name hit(s)\n", len(findings)); err != nil {
140			return err
141		}
142		for _, f := range findings {
143			if _, err := fmt.Fprintf(w, "%s:%d:%d: %s: %q\n", f.Path, f.Line, f.Column, f.Surface, f.Match); err != nil {
144				return err
145			}
146		}
147		return nil
148	}
149	
150	func Run(opts Options) ([]Finding, error) {
151		findings, err := Scan(opts)
152		if err != nil {
153			return nil, err
154		}
155		return findings, Report(opts.Out, findings)
156	}
157	
158	func scanFile(root, rel string) ([]Finding, error) {
159		file, err := os.Open(filepath.Join(root, filepath.FromSlash(rel)))
160		if err != nil {
161			return nil, err
162		}
163		defer file.Close()
164	
165		var findings []Finding
166		scanner := bufio.NewScanner(file)
167		buf := make([]byte, 0, 64*1024)
168		scanner.Buffer(buf, 1024*1024)
169		lineNo := 0
170		for scanner.Scan() {
171			lineNo++
172			line := scanner.Text()
173			for _, r := range rules {
174				if r.rootGo && !isRootGoFile(rel) {
175					continue
176				}
177				loc := r.re.FindStringIndex(line)
178				if loc == nil {
179					continue
180				}
181				findings = append(findings, Finding{
182					Path:    rel,
183					Line:    lineNo,
184					Column:  loc[0] + 1,
185					Surface: r.surface,
186					Match:   line[loc[0]:loc[1]],
187				})
188			}
189		}
190		return findings, scanner.Err()
191	}
192	
193	func shouldSkipDir(rel string) bool {
194		if skippedDirs[rel] {
195			return true
196		}
197		for dir := range skippedDirs {
198			if strings.HasPrefix(rel, dir+"/") {
199				return true
200			}
201		}
202		return false
203	}
204	
205	func isRootGoFile(rel string) bool {
206		return filepath.Dir(rel) == "." && strings.HasSuffix(rel, ".go")
207	}
208	
209	func isTextCandidate(rel string) bool {
210		base := filepath.Base(rel)
211		if strings.HasPrefix(base, ".") && base != ".env" {
212			return false
213		}
214		switch filepath.Ext(rel) {
215		case ".go", ".md", ".txt", ".yaml", ".yml", ".json", ".jsonl", ".toml", ".sh", ".py", ".env":
216			return true
217		default:
218			return base == "Makefile" || base == "Dockerfile" || base == "go.mod"
219		}
220	}
