30	func TestScanSkipsAllowlistedHistoricalAndExternalPaths(t *testing.T) {
31		root := t.TempDir()
32		writeFile(t, root, "docs/research/archive.md", "Run ddx-agent from ~/.config/agent.\n")
33		writeFile(t, root, "docs/helix/plan.md", "DDx Agent used .agent state.\n")
34		writeFile(t, root, ".ddx/beads.jsonl", `{"title":"ddx-agent"}`+"\n")
35		writeFile(t, root, ".agents/skills/ddx/SKILL.md", "The .agents directory is external.\n")
36		writeFile(t, root, ".claude/skills/ddx/SKILL.md", "The old ddx-agent skill copy is historical.\n")
37	
38		findings, err := Scan(Options{Root: root})
39		if err != nil {
40			t.Fatalf("Scan() error = %v", err)
41		}
42		if len(findings) != 0 {
43			t.Fatalf("Scan() findings = %#v, want none", findings)
44		}
45	}
